/* Olho 3D que segue o ponteiro, desenhado em WebGL dentro da bubble do chat.
   A pupila rosa vem do desenho original; esclera, íris, luz e pálpebras são calculadas. */
(() => {
if (!document.getElementById('olho-palco')) return;
const BASE = "data:image/jpeg;base64,";
const HALO = "data:image/png;base64,";
const palco = document.getElementById('olho-palco');
const tela = document.getElementById('olho-tela');
const reduz = matchMedia('(prefers-reduced-motion: reduce)').matches;

const gl = tela.getContext('webgl', { antialias: false, premultipliedAlpha: false });
if (!gl) {
  const img = new Image(); img.src = BASE; img.alt = ''; palco.appendChild(img);
  return;
}

const vs = `attribute vec2 p; varying vec2 vUv;
void main(){ vUv = vec2(p.x*.5+.5, .5-p.y*.5); gl_Position = vec4(p,0.,1.); }`;

const fs = `precision highp float;
varying vec2 vUv;
uniform sampler2D tBase, tHalo;
uniform vec2 uRot;      // giro do globo (horizontal, vertical)
uniform float uFecha;   // 0 aberto, 1 fechado
uniform float uAA;      // tamanho de 1 pixel em unidades da tela
uniform float uTempo;
const vec2 SIZE = vec2(129., 115.);
const vec2 PUP = vec2(59.5, 62.);   // centro da pupila no desenho
const float R = .9;                 // raio do globo (o resto é a órbita)
const float RI = .47;               // raio da íris no globo

vec3 girar(vec3 v, vec2 r){
  float cb = cos(r.y), sb = sin(r.y);
  v = vec3(v.x, v.y*cb - v.z*sb, v.y*sb + v.z*cb);
  float ca = cos(r.x), sa = sin(r.x);
  return vec3(v.x*ca - v.z*sa, v.y, v.x*sa + v.z*ca);
}
float hash(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }
float ruido(vec2 p){
  vec2 i = floor(p), f = fract(p); f = f*f*(3.-2.*f);
  return mix(mix(hash(i), hash(i+vec2(1,0)), f.x), mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), f.x), f.y);
}
vec3 amostra(sampler2D t, vec2 q){ return texture2D(t, clamp(q, vec2(.5), SIZE-.5) / SIZE).rgb; }

void main(){
  vec2 p = vUv*2. - 1.;            // x para a direita, y para baixo
  float r = length(p);
  float aa = max(uAA * 1.5, .004);

  // órbita: pele escura com sombra que afunda em direção ao globo
  vec3 orbita = mix(vec3(.32,.11,.33), vec3(.11,.03,.12), smoothstep(1.02, R - .02, r));
  vec3 col = orbita;

  if (r < R + aa) {
    vec2 s = p / R;
    float z = sqrt(max(1. - dot(s, s), 0.));
    vec3 n = vec3(s, z);                   // normal na visão
    vec3 t = girar(n, uRot);               // ponto no globo, já girado para o ponteiro

    // esclera: branco lilás, rosada nas laterais, com veias finas
    float lat = 1. - t.z;
    vec3 esc = mix(vec3(.97,.94,.99), vec3(.93,.78,.92), smoothstep(.15, 1.2, lat));
    float ang = atan(t.y, t.x);
    float veia = smoothstep(.93, 1., sin(ang*7. + ruido(t.xy*6.)*5.)) * smoothstep(.35, 1., lat) * step(0., t.z + .3);
    esc = mix(esc, vec3(.86,.42,.66), veia * .35);

    // íris: fibras radiais lilás/rosa e anel escuro na borda (limbo)
    float d = length(t.xy) * step(0., t.z);
    float dn = d / RI;
    float fibras = ruido(vec2(ang*16., dn*3.)) * .6 + ruido(vec2(ang*41., dn*7.)) * .4;
    vec3 iris = mix(vec3(.93,.52,.80), vec3(.62,.42,.86), smoothstep(.2, .95, dn));
    iris *= .78 + .38 * fibras;
    iris = mix(iris, vec3(.30,.09,.34), smoothstep(.72, 1., dn));
    // pupila rosa do desenho original, colada no centro da íris
    vec2 q = PUP + (t.xy / RI) * 31.;
    float a = texture2D(tHalo, clamp(q, vec2(.5), SIZE-.5) / SIZE).r * step(0., t.z);
    vec3 pup = amostra(tBase, q);
    iris = mix(iris, pup * vec3(1.02,.96,1.02), a);
    float mIris = smoothstep(RI + .012, RI - .012, d) * step(0., t.z);
    col = mix(esc, iris, mIris);

    // luz principal de cima à esquerda, sombra de volume e da órbita
    vec3 L = normalize(vec3(-.45, -.6, .66));
    float dif = .62 + .38 * max(dot(n, L), 0.);
    col *= dif;
    col = mix(col * vec3(.48,.28,.55), col, smoothstep(.0, .62, z));   // escurece na borda do globo
    col *= mix(.72, 1., smoothstep(-R, -.15, p.y));                     // sombra da sobrancelha

    // pálpebras: descem/sobem sobre o globo e fazem sombra
    float f = uFecha;
    float ySup = mix(-1.05, .08, f) + .32 * p.x*p.x * (1. - .4*f);
    float yInf = mix(1.05, .08, f) - .22 * p.x*p.x * (1. - .4*f);
    col *= 1. - .45 * smoothstep(.0, 1., f*3.) * exp(-max(p.y - ySup, 0.) / .07);
    col *= 1. - .25 * smoothstep(.0, 1., f*3.) * exp(-max(yInf - p.y, 0.) / .05);

    // brilho da córnea (fica parado enquanto o olho gira: dá a sensação de vidro)
    vec3 H = normalize(L + vec3(0,0,1));
    float spec = pow(max(dot(n, H), 0.), 70.);
    vec2 jan = (s - vec2(-.36, -.40)) / vec2(.20, .13);
    float janela = smoothstep(1., .55, length(jan));
    float ponto = smoothstep(.07, .02, length(s - vec2(.30, .34)));
    float vis = smoothstep(.9, .3, f);
    col += (spec * .55 + janela * .75 + ponto * .18) * vis;

    // pele das pálpebras por cima
    float cimaM = smoothstep(ySup + aa, ySup - aa, p.y);
    float baixoM = smoothstep(yInf - aa, yInf + aa, p.y);
    vec3 pele = mix(vec3(.45,.17,.44), vec3(.24,.07,.26), smoothstep(-1., .1, p.y));
    vec3 cilio = vec3(.13,.03,.14);
    float linhaS = exp(-abs(p.y - ySup) / .025);
    float linhaI = exp(-abs(p.y - yInf) / .02);
    col = mix(col, mix(pele, cilio, linhaS), cimaM * step(.001, f));
    col = mix(col, mix(pele * .9, cilio, linhaI), baixoM * step(.001, f));

    col = mix(orbita, col, smoothstep(R + aa, R - aa, r));
  }
  gl_FragColor = vec4(col, 1.);
}`;

function sh(type, src){
  const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s));
  return s;
}
const prog = gl.createProgram();
gl.attachShader(prog, sh(gl.VERTEX_SHADER, vs));
gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, fs));
gl.linkProgram(prog); gl.useProgram(prog);
const buf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buf);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]), gl.STATIC_DRAW);
const loc = gl.getAttribLocation(prog, 'p');
gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
const U = n => gl.getUniformLocation(prog, n);
const uRot = U('uRot'), uFecha = U('uFecha'), uAA = U('uAA'), uTempo = U('uTempo');

function textura(src, unidade, nome){
  return new Promise(res => {
    const img = new Image();
    img.onload = () => {
      const t = gl.createTexture();
      gl.activeTexture(gl.TEXTURE0 + unidade); gl.bindTexture(gl.TEXTURE_2D, t);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, img);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.uniform1i(U(nome), unidade); res();
    };
    img.src = src;
  });
}

function ajustar(){
  const r = tela.getBoundingClientRect(), dpr = Math.min(devicePixelRatio || 1, 3);
  tela.width = Math.max(1, Math.round(r.width * dpr)); tela.height = Math.max(1, Math.round(r.height * dpr));
  gl.viewport(0, 0, tela.width, tela.height);
  gl.uniform1f(uAA, 2 / tela.width);
}
addEventListener('resize', ajustar);
if ('ResizeObserver' in window) new ResizeObserver(ajustar).observe(tela);

// --- olhar ---
const MAX_YAW = 0.5, MAX_PITCH = 0.42;
let alvo = [0,0], rot = [0,0];
function mirar(px, py){
  const r = tela.getBoundingClientRect();
  const ex = r.left + r.width/2, ey = r.top + r.height/2;
  const dx = px - ex, dy = py - ey, dist = Math.hypot(dx, dy) || 1;
  const f = Math.min(dist / 320, 1), s = Math.sqrt(f);
  alvo = [dx/dist * s * MAX_YAW, dy/dist * s * MAX_PITCH];
}
addEventListener('pointermove', e => mirar(e.clientX, e.clientY));
addEventListener('pointerdown', e => mirar(e.clientX, e.clientY));
document.addEventListener('pointerleave', () => { alvo = [0,0]; });

// --- pálpebras: piscadas rápidas e, às vezes, uma pesada de sono ---
let mov = null, proxMov = 2.2;
function novoMovimento(t){
  if (Math.random() < .3) return [t, .9, 1.1, 1.2, .55];
  return [t, .11, .06, .19, 1];
}
function fechamentoEm(t){
  if (!mov) return 0;
  const [t0, d, p, u, m] = mov, e = t - t0;
  const suave = x => x * x * (3 - 2 * x);
  if (e < d) return m * suave(e / d);
  if (e < d + p) return m;
  if (e < d + p + u) return m * (1 - suave((e - d - p) / u));
  mov = null; return 0;
}
const t0 = performance.now(); let antes = t0;
function quadro(agora){
  const t = (agora - t0) / 1000, dt = Math.min((agora - antes) / 1000, .05); antes = agora;
  const k = reduz ? 1 : 1 - Math.pow(0.0008, dt);
  rot[0] += (alvo[0] - rot[0]) * k; rot[1] += (alvo[1] - rot[1]) * k;
  if (!reduz && !mov && t > proxMov) {
    mov = novoMovimento(t);
    proxMov = t + (Math.random() < .2 ? .45 : 3 + Math.random() * 4);
  }
  gl.uniform2f(uRot, rot[0], rot[1]);
  gl.uniform1f(uFecha, fechamentoEm(t));
  gl.uniform1f(uTempo, t);
  gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  requestAnimationFrame(quadro);
}

Promise.all([textura(BASE, 0, 'tBase'), textura(HALO, 1, 'tHalo')]).then(() => {
  ajustar(); requestAnimationFrame(quadro);
});
})();
